bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try {
 const q=await db.query("SELECT r.revision,r.delivery_key,r.status,r.paid_message_id,COUNT(l.ledger_id) FILTER (WHERE l.kind=$2)::int AS purchases,COUNT(l.ledger_id) FILTER (WHERE l.kind=$3)::int AS refunds FROM videobot_post_receipts r LEFT JOIN videobot_stars_ledger l ON l.delivery_key=r.delivery_key WHERE r.listing_id=(SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1) GROUP BY r.revision,r.delivery_key,r.status,r.paid_message_id ORDER BY r.revision",[4691,'paid','refunded']);
 if(q.rowCount<2)process.exitCode=61;
 else {
  const n=q.rows.map(x=>({rev:Number(x.revision),paid:Number(x.paid_message_id),purchases:Number(x.purchases),refunds:Number(x.refunds)}));
  const original=n.find(x=>x.paid===4691);
  const current=n.filter(x=>x.paid!==4691);
  if(original && original.purchases<original.refunds)process.exitCode=81;
  else if(current.some(x=>x.purchases>x.refunds))process.exitCode=82;
  else if(n.some(x=>x.purchases>0))process.exitCode=72;
  else console.log('NO_BUYERS_OR_REFUNDS_FOR_REPOST=PASS');
 }
} catch(error){console.error('LEDGER_RECONCILE_DIAGNOSTIC='+String(error?.code??'UNKNOWN').slice(0,8));process.exitCode=79}finally{await db.end()}
JS
